[11369] = {id=11369,name="WANTED: A Black Stalker Egg",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3716,mapID=111,description="There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies. I have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction. If you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.",starts={{npcID=24369,x=0.75,y=0.37,zoneID=3703}},ends={{npcID=24369,x=0.75,y=0.37,zoneID=3703}},coords={x=0.75,y=0.37,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: A Black Stalker Egg",db2QuestInfoID=85,db2QuestInfoName="Heroic"},
