[11371] = {id=11371,name="WANTED: Coilfang Myrmidons",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3715,mapID=263,description="Mah'duun hears and obeys, and I now ask you to be my instrument. It has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir. I will accept nothing less than their utter annihilation.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Coilfang Myrmidons",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
