[11376] = {id=11376,name="WANTED: Malicious Instructors",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3789,mapID=260,description="Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth . Go to Auchindoun, seek them out, kill them all. If you cannot accomplish so simple a task, we do not have anything further to say to one another.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Malicious Instructors",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
