[11383] = {id=11383,name="WANTED: Rift Lords",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=2366,mapID=111,description="Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords . But, Mah'duun does not know exactly when. I know that does not make sense, but the voice on the winds was not more specific. Travel to the Black Morass through the Caverns of Time and the way shall be made clear.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Rift Lords",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
