[11385] = {id=11385,name="WANTED: Sunseeker Channelers",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3847,mapID=111,description="It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today. They are to be found within the Botanica at Tempest Keep. You want the bounty, you kill the channelers.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Sunseeker Channelers",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
