[11387] = {id=11387,name="WANTED: Tempest-Forge Destroyers",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3849,mapID=111,description="There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled. Go to Tempest Keep, find the tempest-forge destroyers and destroy them. Then you may return to collect the bounty.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Tempest-Forge Destroyers",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
