[11389] = {id=11389,name="WANTED: Arcatraz Sentinels",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3848,mapID=270,description="The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help. Mah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels. Accomplish this and today's bounty is yours.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Arcatraz Sentinels",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
