[11500] = {id=11500,name="WANTED: Sisters of Torment",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4131,mapID=111,description="It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang. Mah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas. You will do this thing to earn the bounty, or you will not.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="world",worldTaskTitle="WANTED: Sisters of Torment",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
